#include <stdio.h>

int main() {
    int n;
    double total = 0.0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        double venta;
        scanf("%lf", &venta);
        total += venta;
    }
    printf("%.2f\n", total / n);
    return 0;
}

